		PlaceObj('ModItemFolder', {
			'name', "Grit",
		}, {
			PlaceObj('ModItemCharacterEffectCompositeDef', {
				'Group', "Health",
				'Id', "TrueGrit",
				'SortKey', 6,
				'Parameters', {
					PlaceObj('PresetParamNumber', {
						'Name', "outOfCoverGrit",
						'Value', 15,
						'Tag', "<outOfCoverGrit>",
					}),
					PlaceObj('PresetParamNumber', {
						'Name', "nextToEnemyGrit",
						'Value', 15,
						'Tag', "<nextToEnemyGrit>",
					}),
				},
				'object_class', "Perk",
				'unit_reactions', {
					PlaceObj('UnitReaction', {
						Event = "OnEndTurn",
						Handler = function (self, target)
							-- out of cover buff
							if not target:IsUsingCover() and g_Combat:AreEnemiesAware(g_CurrentTeam) then
								target:ApplyTempHitPoints(self:ResolveValue("outOfCoverGrit"))
							end
							
							-- next to enemy buff
							local nearestEnemy = GetNearestEnemy(target)
							if nearestEnemy and target:IsAdjacentTo(nearestEnemy) then
								target:ApplyTempHitPoints(self:ResolveValue("nextToEnemyGrit"))
							end
						end,
						param_bindings = false,
					}),
				},
				'DisplayName', T(589779671581, --[[ModItemCharacterEffectCompositeDef TrueGrit DisplayName]] "Авангард"),
				'Description', T(835802440630, --[[ModItemCharacterEffectCompositeDef TrueGrit Description]] "Вам дается <color EmStyle>Сила воли</color> (<color EmStyle><outOfCoverGrit></color>), если вы заканчиваете ход вне <color EmStyle>укрытия</color>.\n\nВам дается <color EmStyle>Сила воли</color> (<color EmStyle><nextToEnemyGrit></color>), если вы заканчиваете ход <color EmStyle>вплотную</color> к врагу."),
				'Icon', "UI/Icons/Perks/ContestGround",
				'Tier', "Silver",
				'Stat', "Health",
				'StatValue', 80,
			}),
			PlaceObj('ModItemConstDef', {
				Comment = "Grit(TempHitPoints) stacks up to this amount.",
				group = "Combat",
				id = "MaxGrit",
				value = 50,
			}),
			}),
		PlaceObj('ModItemFolder', {
			'name', "Healing",
		}, {
			PlaceObj('ModItemCombatAction', {
				ActionPoints = 2000,
				ActivePauseBehavior = "queue",
				AimType = "melee",
				ConfigurableKeybind = false,
				Description = T(573799800858, --[[ModItemCombatAction Bandage Description]] "Оказание медицинской помощи раненому союзнику. Требует времени, в течение которого вы не сможете совершать другие действия. Перевязываемый союзник не может перемещаться, но может атаковать.\n\n<color EmStyle>Тяжелое ранение</color>: стабилизация состояния <color EmStyle>союзника</color>. Другие случаи: <color EmStyle>восстановление <hp>% макс. запаса ОЗ раненого</color> (в зависимости от навыка «<color EmStyle><color EmStyle>Медицина</color></color>»). Ваш персонаж переходит в положение <color EmStyle>присев</color>."),
				DisplayName = T(616312070908, --[[ModItemCombatAction Bandage DisplayName]] "Перевязка"),
				EvalTarget = function (self, units, target, args)
					local unit = units[1]
					if not target or unit:IsOnEnemySide(target) then return -1 end
					if not target:HasStatusEffect("Bleeding") and (target.HitPoints >= target.MaxHitPoints)
					and not target:HasStatusEffect("Inaccurate")
					and not target:HasStatusEffect("Slowed") 
					then return -1 end
					
					return (200 - target.HitPoints) or 0
				end,
				GetAPCost = function (self, unit, args)
					local medicine = self:GetAttackWeapons(unit, args)
					if not medicine then return -1 end -- can be valid in AI PrecalcAction
					return self.ActionPoints
				end,
				GetActionDescription = function (self, units)
					local unit = units[1]
					local medkit = self:GetAttackWeapons(unit)
					local hp = unit:CalcHealAmount(medkit) or 0
					local percent = MulDivRound(100, hp, unit.MaxHitPoints)
					if LastLoadedOrLoadingIMode == "IModeCombatMelee" then
						return T{930612158384, "Select the unit you would like to bandage, healing them for <hp>% of their max HP.", hp = percent}
					end
					
					return T{self.Description, hp = percent}
				end,
				GetAnyTarget = function (self, units)
					return GetBandageTargets(units[1], "any", "ignore")
				end,
				GetAttackWeapons = function (self, unit, args)
					return GetUnitEquippedMedicine(unit)
				end,
				GetDefaultTarget = function (self, unit)
					local units = {unit}
					if self:EvalTarget(units, unit) > 0 then
						return unit
					end
					return CombatAction.GetDefaultTarget(self, unit)
				end,
				GetTargets = function (self, units)
					return GetBandageTargets(units[1], "all", "ignore")
				end,
				GetUIState = function (self, units, args)
					local unit = units[1]
					
					if g_Combat and not unit:HasAP(self.ActionPoints) then 
						return "disabled", GetUnitNoApReason(unit) 
					end
					
					if not GetBandageTargets(unit, "any", "reachable") then
						return "disabled", AttackDisableReasons.NoBandageTarget
					end
					
					return "enabled"
				end,
				Icon = "UI/Icons/Hud/stop_bleeding",
				IdDefault = "Bandagedefault",
				IsAimableAttack = false,
				KeybindingFromAction = "actionRedirectBandage",
				MoveStep = true,
				MultiSelectBehavior = "first",
				Parameters = {
					PlaceObj('PresetParamPercent', {
						'Name', "selfheal",
						'Value', 70,
						'Tag', "<selfheal>%",
					}),
					PlaceObj('PresetParamPercent', {
						'Name', "base_heal",
						'Value', 20,
						'Tag', "<base_heal>%",
					}),
					PlaceObj('PresetParamPercent', {
						'Name', "medical_max_heal",
						'Value', 30,
						'Tag', "<medical_max_heal>%",
					}),
					PlaceObj('PresetParamNumber', {
						'Name', "ReviveConditionLoss",
						'Value', 10,
						'Tag', "<ReviveConditionLoss>",
					}),
					PlaceObj('PresetParamNumber', {
						'Name', "MaxConditionHPRestore",
						'Value', 120,
						'Tag', "<MaxConditionHPRestore>",
					}),
				},
				QueuedBadgeText = T(260416147827, --[[ModItemCombatAction Bandage QueuedBadgeText]] "ПЕРЕВЯЗКА"),
				RequireState = "any",
				RequireWeapon = true,
				Run = function (self, unit, ap, ...)
					unit:SetActionCommand("Bandage", self.id, ap, ...)
				end,
				SortKey = 10,
				UIBegin = function (self, units, args)
					if self:GetAnyTarget(units) then
						if units then 
							table.sort(units, function (a,b) 
								return a.Medical > b.Medical and self:GetAttackWeapons(a)
							end)
						end
						CombatActionAttackStart(self, units, args, "IModeCombatMelee")
					end
				end,
				group = "Consumables",
				id = "Bandage",
			}),
			PlaceObj('ModItemCode', {
				'name', "Systems_Wounds_HealWounds",
				'CodeFileName', "Code/Systems_Wounds_HealWounds.lua",
			}),
			PlaceObj('ModItemCode', {
				'name', "System_Wounds_OperationHeal",
				'CodeFileName', "Code/System_Wounds_OperationHeal.lua",
			}),
			}),
		PlaceObj('ModItemFolder', {
			'name', "Character effects",
		}, {
			PlaceObj('ModItemCharacterEffectCompositeDef', {
				'Group', "System",
				'Id', "Headshot",
				'Parameters', {},
				'object_class', "StatusEffect",
				'msg_reactions', {},
				'unit_reactions', {},
				'DisplayName', T(664162876607, --[[ModItemCharacterEffectCompositeDef Headshot DisplayName]] "Ранение в голову"),
				'Description', "",
				'OnAdded', function (self, obj)
					if obj.TempHitPoints > 0 then return end
					local hp = obj.TempHitPoints + obj.HitPoints
					if obj:Random(hp) < 5  then
					obj:AddStatusEffect("Unconscious")
					elseif obj:Random(hp) < 20   then
					obj:AddStatusEffect("Blinded")
					end
				end,
				'OnRemoved', function (self, obj)  end,
				'type', "Debuff",
				'lifetime', "Until End of Turn",
