		PlaceObj('ModItemFolder', {
			'name', "CTHMod",
		}, {
			PlaceObj('ModItemChanceToHitModifier', {
				CalcValue = function (self, attacker, target, body_part_def, action, weapon1, weapon2, lof, aim, opportunity_attack, attacker_pos, target_pos)
					if opportunity_attack or not IsKindOf(weapon1, "Firearm") or not IsKindOf(target, "Unit") then 
						return false, 0 
					end
					local target_stance = target:GetHitStance()
					if target_stance == "Prone" then
						local value = self:ResolveValue("PronePenalty") 
						return true, value, T(904752344471, "Target Prone")
					end
					
					local cover, any, coverage
					if weapon1 then
						local ignoreCth = weapon1:HasComponent("IgnoreCoverCtHWhenFullyAimed") and IsFullyAimedAttack(aim)
						if not ignoreCth and (opportunity_attack or target:IsAware()) and not target:HasStatusEffect("Exposed") then
							cover, any, coverage = target:GetCoverPercentage(attacker_pos, target_pos)
						end
					end
					
					-- force exposed when aiming/shooting
					local melee_attack = action and action.ActionType == "Melee Attack"
					cover = not target.aim_action_id and not melee_attack and cover
					
					if cover then
						local name = false
						local exposed_value = self:ResolveValue("ExposedCover")
						local full_value = self:ResolveValue("Cover")
						
						if CheckSightCondition(attacker, target, const.usObscured) then
							exposed_value = exposed_value + const.EnvEffects.DustStormCoverCTHPenalty
							full_value = full_value + const.EnvEffects.DustStormCoverCTHPenalty
							name = T(548829641491, "Behind Cover (Dust Storm)")
						end
						
						local value = InterpolateCoverEffect(coverage, full_value, exposed_value)
						local metaText = false
					
						if value < exposed_value then
							return true, value, name, metaText, "Cover"
						end
					end
					if target_stance == "Crouch" then
						local value = self:ResolveValue("CrouchPenalty")
						return true, value, T(309253003316, "Target Crouched")
					end
					return false, 0
				end,
				Parameters = {
					PlaceObj('PresetParamNumber', {
						'Name', "Cover",
						'Value', -20,
						'Tag', "<Cover>",
					}),
					PlaceObj('PresetParamNumber', {
						'Name', "ExposedCover",
						'Value', -5,
						'Tag', "<ExposedCover>",
					}),
					PlaceObj('PresetParamNumber', {
						'Name', "CrouchPenalty",
						'Value', -5,
						'Tag', "<CrouchPenalty>",
					}),
					PlaceObj('PresetParamNumber', {
						'Name', "PronePenalty",
						'Value', -10,
						'Tag', "<PronePenalty>",
					}),
				},
				RequireTarget = true,
				display_name = T(689049582614, --[[ModItemChanceToHitModifier Default RangeAttackTargetStanceCover display_name]] "В укрытии"),
				group = "Default",
				id = "RangeAttackTargetStanceCover",
			}),
			PlaceObj('ModItemChanceToHitModifier', {
				CalcValue = function (self, attacker, target, body_part_def, action, weapon1, weapon2, lof, aim, opportunity_attack, attacker_pos, target_pos)
					if not attacker or not target then 
						return false, 0
					end
					
					if true then 
						return false, 0
					end
					
					local param
					local metaText = {}
					
					local extra = 0
					if action.id == "BurstFire" then
						param = "burst_max_penalty"
					elseif action.id == "AutoFire" then
						param = "auto_max_penalty"
					elseif action.id == "MGBurstFire" then
						if g_Overwatch[attacker] and g_Overwatch[attacker].permanent then
							param = "mg_burst_max_penalty"
						else
							param = "mg_burst_max_held_penalty"
							if weapon1 and weapon1:IsCumbersome() then
								extra = self:ResolveValue("mg_burst_cumbersome_penalty")
							end
						end
					elseif action.id == "GrizzlyPerk" then
						param = "mg_burst_max_penalty"
						metaText[#metaText + 1] = GrizzlyPerk.DisplayName
					else
						return false, 0
					end
					
					local penalty = self:ResolveValue("base_penalty")
					local pb_dist = const.Weapons.PointBlankRange * const.SlabSizeX
					local dist = attacker_pos:Dist(target_pos)
					
					if dist > pb_dist then
						-- scale in the distance after point-blank range to max penalty
						local max_dist = self:ResolveValue("max_dist") * const.SlabSizeX		
						local max_penalty = self:ResolveValue(param) + extra
						
						dist = Min(dist, max_dist) - pb_dist
						max_dist = max_dist - pb_dist
						penalty = penalty + Min(-1, MulDivRound(dist, max_penalty - penalty, max_dist))
					end
					
					if penalty == 0 then
						return false, 0
					end
					
					if action.id == "BurstFire" then
						return true, penalty, T(913932180355, "Burst Fire"), #metaText ~= 0 and metaText
					end
					
					return true, penalty, false, #metaText ~= 0 and metaText
				end,
				Parameters = {
					PlaceObj('PresetParamNumber', {
						'Name', "max_dist",
						'Value', 14,
						'Tag', "<max_dist>",
					}),
					PlaceObj('PresetParamPercent', {
						'Name', "base_penalty",
						'Tag', "<base_penalty>%",
					}),
					PlaceObj('PresetParamPercent', {
						'Name', "auto_max_penalty",
						'Value', 10,
						'Tag', "<auto_max_penalty>%",
					}),
					PlaceObj('PresetParamPercent', {
						'Name', "burst_max_penalty",
						'Value', 5,
						'Tag', "<burst_max_penalty>%",
					}),
					PlaceObj('PresetParamPercent', {
						'Name', "mg_burst_max_penalty",
						'Value', 10,
						'Tag', "<mg_burst_max_penalty>%",
					}),
					PlaceObj('PresetParamPercent', {
						'Name', "mg_burst_max_held_penalty",
						'Value', 50,
						'Tag', "<mg_burst_max_held_penalty>%",
					}),
					PlaceObj('PresetParamPercent', {
						'Name', "mg_burst_cumbersome_penalty",
						'Value', -20,
						'Tag', "<mg_burst_cumbersome_penalty>%",
					}),
				},
				display_name = T(487905424717, --[[ModItemChanceToHitModifier Default Autofire display_name]] "Автоогонь"),
				group = "Default",
				id = "Autofire",
			}),
			PlaceObj('ModItemChanceToHitModifier', {
				CalcValue = function (self, attacker, target, body_part_def, action, weapon1, weapon2, lof, aim, opportunity_attack, attacker_pos, target_pos)
					local num = aim
					local min_bonus = self:ResolveValue("MinBonus")
					local min_dex = self:ResolveValue("MinDex")
					local dex_scale = self:ResolveValue("DexScale")
					local dex = attacker.Dexterity
					local mrk = attacker.Marksmanship
					local level = attacker:GetLevel()
					
					if IsKindOfClasses(weapon1, "FirearmProperties", "MeleeWeaponProperties") then
						min_bonus = weapon1.AimAccuracy
					end
					
					local modifyVal, compDef
					local metaText = {}
					
					-- Light Stock
					modifyVal, compDef = GetComponentEffectValue(weapon1, "ReduceAimAccuracy", "cth_penalty")
					if modifyVal then
						min_bonus = Max(1, MulDivRound(min_bonus, 100 - modifyVal, 100))
						metaText[#metaText + 1] = compDef.DisplayName
					end
					
					
					
					
					-- Quick prism
					modifyVal, compDef = GetComponentEffectValue(weapon1, "FirstShotIncreasedAim", "min_aim")
					if modifyVal then
						local reaction = table.find_value(WeaponComponentEffects.FirstShotIncreasedAim.unit_reactions, "Event", "OnCalcMinAimActions")
						reaction = reaction and reaction.Handler
						if reaction then
							local result = reaction(weapon1, target, 0, attacker, target, action, weapon1)
							if result and result == num then
								metaText[#metaText + 1] = compDef.DisplayName
							end
						end
					end
					
					-- Heavy Stock
					if IsFullyAimedAttack(num) then
						modifyVal, compDef = GetComponentEffectValue(weapon1, "BonusAccuracyWhenFullyAimed", "BonusAccuracyWhenFullyAimed")
						if modifyVal then
							min_bonus = Max(1, MulDivRound(min_bonus, 100 - modifyVal, 100))
							metaText[#metaText + 1] = compDef.DisplayName
						end
					end
					
					-- Improved Sight
					modifyVal, compDef = GetComponentEffectValue(weapon1, "AccuracyBonusWhenAimed", "bonus_cth")
					if modifyVal then
						min_bonus = Max(1, MulDivRound(min_bonus, 100 - modifyVal, 100))
						metaText[#metaText + 1] = compDef.DisplayName
					end
					
					-- ScopeBonus
					local ScopeAimLevel = GetComponentEffectValue(weapon1, "ScopeMagnification", "ScopeAimLevel") or 0
					if ScopeAimLevel and num > ScopeAimLevel then
						modifyVal, compDef = GetComponentEffectValue(weapon1, "ScopeCTHBonus", "ScopeCTH")
						if modifyVal then
							min_bonus = Max(1, MulDivRound(min_bonus, 100 - modifyVal, 100))
							metaText[#metaText + 1] = compDef.DisplayName
						end
					end
					
					--local bonus = num * min_bonus + MulDivRound(Max(0, dex - min_dex) * num, dex_scale, 100)
					local bonus = num * MulDivRound(min_bonus,mrk,100)
					-- target camo
					
					
					-- Forward Grip
					modifyVal, compDef = GetComponentEffectValue(weapon1, "FirstAimBonusModifier", "first_aim_bonus")
					if modifyVal then
						bonus = bonus + MulDivRound(min_bonus, modifyVal, 100)
						metaText[#metaText + 1] = compDef.DisplayName
					end
					
					return num > 0, bonus,  T{762331260877, "Aiming (x<aim_mod>)", aim_mod = num}, #metaText ~= 0 and metaText
				end,
				Parameters = {
					PlaceObj('PresetParamNumber', {
						'Name', "MinBonus",
						'Value', 2,
						'Tag', "<MinBonus>",
					}),
					PlaceObj('PresetParamNumber', {
						'Name', "MinDex",
						'Value', 40,
						'Tag', "<MinDex>",
					}),
					PlaceObj('PresetParamPercent', {
						'Name', "DexScale",
						'Value', 10,
						'Tag', "<DexScale>%",
					}),
				},
				display_name = T(740390022763, --[[ModItemChanceToHitModifier Default Aim display_name]] "Прицеливание"),
				group = "Default",
				id = "Aim",
				param_bindings = {},
			}),
			PlaceObj('ModItemChanceToHitModifier', {
				CalcValue = function (self, attacker, target, body_part_def, action, weapon1, weapon2, lof, aim, opportunity_attack, attacker_pos, target_pos)
					if attacker and IsKindOf(weapon1, "FirearmProperties") and weapon1:HasPointBlankBonus() and attacker:IsPointBlankRange(target) then
						return true, self:ResolveValue("bonus")
					end
					
					return false, 0
				end,
				Parameters = {
					PlaceObj('PresetParamPercent', {
						'Name', "bonus",
						'Value', 15,
						'Tag', "<bonus>%",
					}),
				},
				display_name = T(277372719027, --[[ModItemChanceToHitModifier Default Laser display_name]] "Подсветка лазером"),
				group = "Default",
				id = "Laser",
			}),
			PlaceObj('ModItemChanceToHitModifier', {
				CalcValue = function (self, attacker, target, body_part_def, action, weapon1, weapon2, lof, aim, opportunity_attack, attacker_pos, target_pos)
					if attacker and IsCloser(target, attacker, 5 * const.SlabSizeX + 1) and IsKindOf(weapon1, "Firearm") then
						if IsKindOf(weapon1, "Pistol") then return true, self:ResolveValue("bonus") end
						if IsKindOf(weapon1, "SubmachineGun") then return true, self:ResolveValue("bonus") end
						return true, self:ResolveValue("bonus")
					end
					
					return false, 0
				end,
				Parameters = {
					PlaceObj('PresetParamPercent', {
						'Name', "bonus",
						'Value', 30,
						'Tag', "<bonus>%",
					}),
				},
				display_name = T(733589978306, --[[ModItemChanceToHitModifier Default PointBlank display_name]] "Стрельба в упор"),
				group = "Default",
				id = "PointBlank",
			}),
			PlaceObj('ModItemChanceToHitModifier', {
				CalcValue = function (self, attacker, target, body_part_def, action, weapon1, weapon2, lof, aim, opportunity_attack, attacker_pos, target_pos)
					if attacker and not IsCloser(target, attacker, 5 * const.SlabSizeX + 1) and IsKindOf(weapon1, "Firearm") then
						if attacker:HasStatusEffect("suppressionLight") then
							return true, -10 end
								if attacker:HasStatusEffect("suppressionMedium") then
							return true, -20 end
								if attacker:HasStatusEffect("suppressionHeavy") then
							return true, -30 end
								if attacker:HasStatusEffect("suppressionHeavy2") then
							return true, -50 end
								if attacker:HasStatusEffect("suppressionPinned") then
							return true, -70 end
					end
					return false, 0
				end,
				display_name = T(733589978306, --[[ModItemChanceToHitModifier Default Suppression display_name]] "Подавление"),
				group = "Default",
				id = "Suppression",
			}),
			PlaceObj('ModItemChanceToHitModifier', {
				CalcValue = function (self, attacker, target, body_part_def, action, weapon1, weapon2, lof, aim, opportunity_attack, attacker_pos, target_pos)
					if attacker and IsKindOfClasses(weapon1, "Firearm", "Firearm") and not IsCloser(target, attacker, 3 * const.SlabSizeX + 1) then
					-- 
					local sight = attacker:GetSightRadius() + 5 * const.SlabSizeX
					
					local attacker_pos = attacker:GetPos()
					local target_pos = IsPoint(target) and target or target:GetPos()
					local dist = Max(1,attacker_pos:Dist(target_pos)/const.SlabSizeX)
					if target then sight = attacker:GetSightRadius(target) end
					
					local hasflashlight = false
					local _, __, weapons = attacker:GetActiveWeapons()
					for i, w in ipairs(weapons) do
						if (w:HasComponent("IgnoreInTheDark") and dist < 15) or w:HasComponent("IgnoreInTheDarkWhenFullyAimed") and IsFullyAimedAttack(aim) then
							hasflashlight = true
						end
					end
					
					if (GameState.Night or GameState.Underground) and not attacker:HasNightVision() and not IsIlluminated(target) and not hasflashlight
					then dist = dist * 1.6 end				
					
					if (GameState.Heat)	then dist = dist * 0.9 	end
					if (GameState.RainLight) then dist = dist * 1.1 end
					if (GameState.RainHeavy or GameState.Fog) then dist = dist * 1.3 end
					if (GameState.FireStorm or GameState.DustStorm)	then dist = dist * 1.5 end
					
					if (attacker:HasStatusEffect("Blinded")) then dist = dist * 3 end
					
					
					local ScopeMagn = GetComponentEffectValue(weapon1, "ScopeMagnification", "ScopeMagnification") or 1
					local ScopeSubMagn = GetComponentEffectValue(weapon1, "ScopeMagnification", "ScopeSubMagnification") or 0
					local ScopeAimLevel = GetComponentEffectValue(weapon1, "ScopeMagnification", "ScopeAimLevel") or 0
					local ScopeCalcMagn = ScopeMagn*10+ScopeSubMagn
					ScopeCalcMagn = ScopeCalcMagn * 1.5/2
					
					local SmallMagn = GetComponentEffectValue(weapon1, "SmallMagnification", "SmallMagnification") or 1
					local SmallSubMagn = GetComponentEffectValue(weapon1, "SmallMagnification", "SmallSubMagnification") or 0
					local SmallAimLevel = GetComponentEffectValue(weapon1, "SmallMagnification", "SmallAimLevel") or 0
					local SmallCalcMagn = SmallMagn*10+SmallSubMagn
					SmallCalcMagn = SmallCalcMagn * 1.5/2
					
					local cth = MulDivRound(100-self:ResolveValue("min"),const.SlabSizeX*100,sight)
					
					
					
					if hasflashlight or not (GameState.Night or GameState.Underground) or IsIlluminated(target)  then
					if ScopeAimLevel>0 and aim >= ScopeAimLevel then 
							local cthmagn = MulDivRound(dist,cth,10*ScopeCalcMagn)
							return true,  -cthmagn, T("Видимость цели ("..ScopeMagn.."."..ScopeSubMagn.."х прицел)")
					end
					if SmallAimLevel>0 and aim >= SmallAimLevel then 
							local cthmagn = MulDivRound(dist,cth,10*SmallCalcMagn)
							return true,  -cthmagn, T("Видимость цели ("..SmallMagn.."."..SmallSubMagn.."х доп. прицел)")
					end
					end
					
					
					local cthIron = MulDivRound(dist,cth,100)					
					
					if GameState.Night or GameState.Underground then
						if hasflashlight or IsIlluminated(target) then 
							return true,  -cthIron, T("Видимость цели (Подсветка)")
						end
						if attacker:HasNightVision() then
							cthIron = floatfloor(cthIron * 1.3,0) 
							return true,  -cthIron, T("Видимость цели (Ночное зрение)")
						end
						return  true,  -cthIron, T("Видимость цели (Ночь)")
					end
						
					
					
					return true,  -cthIron
					end
					return false, 0
				end,
				Parameters = {
					PlaceObj('PresetParamPercent', {
						'Name', "min",
						'Value', 40,
						'Tag', "<min>%",
					}),
				},
				RequireActionType = "Any Ranged Attack",
				display_name = T(254908977776, --[[ModItemChanceToHitModifier Default Distance display_name]] "Видимость цели"),
				group = "Default",
				id = "Distance",
			}),
			PlaceObj('ModItemChanceToHitModifier', {
				CalcValue = function (self, attacker, target, body_part_def, action, weapon1, weapon2, lof, aim, opportunity_attack, attacker_pos, target_pos)
					if attacker and IsKindOf(weapon1, "Firearm") and not IsCloser(target, attacker, 5 * const.SlabSizeX + 1) then
					--local sight = attacker:GetSightRadius() + 5
					local attacker_pos = attacker:GetPos()
					local target_pos = IsPoint(target) and target or target:GetPos()
					local dist = attacker_pos:Dist(target_pos)/const.SlabSizeX
					--if target then sight = attacker:GetSightRadius(target) end
					
					local groupingResult = FirearmGetGrouping(weapon1,dist)
					
						if groupingResult < 100 then
							local cth = 100 - groupingResult
							return true,  -cth/2, T("Влияние кучности оружия на дистанции ("..groupingResult..")")
						end
					end
					return false, 0
				end,
				Parameters = {
					PlaceObj('PresetParamPercent', {
						'Name', "min",
						'Value', 25,
						'Tag', "<min>%",
					}),
				},
				RequireActionType = "Any Ranged Attack",
				display_name = T(353057401634, --[[ModItemChanceToHitModifier Default Grouping display_name]] "Влияние кучности оружия"),
				group = "Default",
				id = "Grouping",
			}),
			PlaceObj('ModItemChanceToHitModifier', {
				CalcValue = function (self, attacker, target, body_part_def, action, weapon1, weapon2, lof, aim, opportunity_attack, attacker_pos, target_pos)
					-- the attacker must not have normal sight to the target (los + sight radius)
					if not attacker or not target or VisibilityCheckAll(attacker, target, nil, const.uvVisible) then
						return false, 0
					end
					
					-- perks that negate the effect
					if not IsKindOf(weapon1, "Firearm") then
						return false, 0
					end
					
					
					local base = 0
					local weapon1, weapon2 = attacker:GetActiveWeapons()
					if weapon1.components.Scope == "LROpticsAdvanced" then
					base = 5
					elseif weapon1.components.Scope == "LROptics" then
					base = 15
					elseif weapon1.components.Scope == "ScopeCOG" then
					base = 25
					elseif weapon1.components.Scope == "ScopeCOGQuick" then
					base = 35
					else base = 50 end
					
					local wis = attacker.Wisdom
					local mrk = attacker.Marksmanship
					
					local skill = 2*(100-wis)+(100-mrk)
					skill=MulDivRound(skill,1,3)
					local debuff = -base-skill
					
					if not attacker.team or not VisibilityCheckAll(attacker.team, target, nil, const.uvVisible) then
						return true, self:ResolveValue("BlindFirePenalty")
					end
					return true, self:ResolveValue("SpotterPenalty"), T(431888134623, "Seen by Spotter")
				end,
				Parameters = {
					PlaceObj('PresetParamPercent', {
						'Name', "SpotterPenalty",
						'Value', -10,
						'Tag', "<SpotterPenalty>%",
					}),
					PlaceObj('PresetParamPercent', {
						'Name', "BlindFirePenalty",
						'Value', -50,
						'Tag', "<BlindFirePenalty>%",
					}),
				},
				RequireActionType = "Any Ranged Attack",
				RequireTarget = true,
				comment = "было -20/-20. Пенальти если не видно цель (или видно тиммейту)",
				display_name = T(126273205496, --[[ModItemChanceToHitModifier Default SeenBySpotter display_name]] "Стрельба вслепую"),
				group = "Default",
				id = "SeenBySpotter",
			}),
			PlaceObj('ModItemChanceToHitModifier', {
				CalcValue = function (self, attacker, target, body_part_def, action, weapon1, weapon2, lof, aim, opportunity_attack, attacker_pos, target_pos)
					if HasVisibilityTo(attacker.team or attacker, target) then
						return false, 0
					end
					if not IsKindOf(weapon1, "Firearm") or not attacker or not target then
						return false, 0
					end
					
					return true, self:ResolveValue("Penalty")
				end,
				Parameters = {
					PlaceObj('PresetParamNumber', {
						'Name', "Penalty",
						'Value', -100,
						'Tag', "<Penalty>",
					}),
				},
				RequireTarget = true,
				comment = "было -50",
				display_name = T(604340497539, --[[ModItemChanceToHitModifier Default NoLineOfSight display_name]] "Нет линии огня"),
				group = "Default",
				id = "NoLineOfSight",
			}),
			PlaceObj('ModItemChanceToHitModifier', {
				CalcValue = function (self, attacker, target, body_part_def, action, weapon1, weapon2, lof, aim, opportunity_attack, attacker_pos, target_pos)
					if action.id ~= "MarkTarget" and action.ActionType ~= "Melee Attack" then return false, 0 end
					if not attacker:HasStatusEffect("Hidden") or not IsKindOf(target, "Unit") or target:IsAware() then return false, 0 end
					return true, self:ResolveValue("bonus")
				end,
				Parameters = {
					PlaceObj('PresetParamPercent', {
						'Name', "bonus",
						'Value', 40,
						'Tag', "<bonus>%",
					}),
				},
				RequireTarget = true,
				comment = "Было 15, сделал 40. Не убивать из стелса это рак",
				display_name = T(621519772188, --[[ModItemChanceToHitModifier Default MeleeStealthStrike display_name]] "Нападение из засады"),
				group = "Default",
				id = "MeleeStealthStrike",
			}),
			PlaceObj('ModItemChanceToHitModifier', {
				CalcValue = function (self, attacker, target, body_part_def, action, weapon1, weapon2, lof, aim, opportunity_attack, attacker_pos, target_pos)
					local cover, any, coverage = attacker:GetCoverPercentage(target)
					local halfcover = cover and cover == const.CoverLow  and coverage > 80
					if (attacker.stance ~= "Prone" and not halfcover) or not weapon1 then
						attacker:RemoveStatusEffect("BipodUnfolded")
						return false,  0
					end
					local value = GetComponentEffectValue(weapon1, "AccuracyBonusProne", "bonus_cth_bipod")
					if IsKindOf(weapon1, "MachineGun") then value = value  end
						attacker:AddStatusEffect("BipodUnfolded")
					return not not value, value
				end,
				display_name = T(839955828537, --[[ModItemChanceToHitModifier Default Bipod display_name]] "Сошки"),
				group = "Default",
				id = "Bipod",
			}),
			PlaceObj('ModItemChanceToHitModifier', {
				CalcValue = function (self, attacker, target, body_part_def, action, weapon1, weapon2, lof, aim, opportunity_attack, attacker_pos, target_pos)
					local value = GetComponentEffectValue(weapon1, "NightsIronsBonus", "NightsIronsBonus")
					if IsKindOf(weapon1, "Firearm") then value = value  end
					return not not value, value
				end,
				display_name = T(373951788563, --[[ModItemChanceToHitModifier Default NightsIronsBonus display_name]] "Контрастный прицел"),
				group = "Default",
				id = "NightsIronsBonus",
			}),
			PlaceObj('ModItemChanceToHitModifier', {
				CalcValue = function (self, attacker, target, body_part_def, action, weapon1, weapon2, lof, aim, opportunity_attack, attacker_pos, target_pos)
					if action.id ~= "MarkTarget" and action.ActionType ~= "Melee Attack" then return false, 0 end
					if IsKindOf(attacker, "Unit") and IsKindOf(target, "Unit") then
						local attackerLevel = attacker:GetLevel()
						local targetLevel = target:GetLevel()
						local hasAdvantage = (attackerLevel - targetLevel) >= self:ResolveValue("levelDiff")
						if hasAdvantage then
							return true,  self:ResolveValue("bonus")
						end
					end
				end,
				Comment = "More accurate attacks against lower level targets",
				Parameters = {
					PlaceObj('PresetParamPercent', {
						'Name', "bonus",
						'Value', 10,
						'Tag', "<bonus>%",
					}),
					PlaceObj('PresetParamNumber', {
						'Name', "levelDiff",
						'Value', 2,
						'Tag', "<levelDiff>",
					}),
