													'ContextUpdateOnOpen', true,
													'OnContextUpdate', function (self, context, ...)
														local modDlg = self:ResolveId("node"):ResolveId("node")
														self:SetText(modDlg:GetWeaponComponentsCombinedEffects())
													end,
													'Translate', true,
													'TextHAlign', "right",
