						'LayoutMethod', "VList",
						'FoldWhenHidden', true,
					}, {
						PlaceObj('XTemplateWindow', {
							'__class', "XText",
							'Id', "idModifications",
							'Margins', box(10, 0, 0, 0),
							'VAlign', "center",
							'MinHeight', 34,
							'TextStyle', "PDABrowserNameSmall",
							'ContextUpdateOnOpen', true,
							'OnContextUpdate', function (self, context, ...)
								local count, max = CountWeaponUpgrades(context)
								self:SetText(T{778177921915, "MODIFICATIONS <right><style PDABrowserSubtitleLight><count></style><style PDABrowserSubtitle>/<max></style>", count = count, max = max})
							end,
							'Translate', true,
							'TextVAlign', "center",
