											'__condition', function (parent, context)
												local unit = GetInventoryUnit()
													if gv_SatelliteView then	
														if unit.Squad and gv_Squads[unit.Squad] and context.sector_id ~= gv_Squads[unit.Squad].CurrentSector then
															return true
														end	
													end
													return false
											end,
											'__class', "XText",
