				PlaceObj('XTemplateFunc', {
					'name', "DeselectMultiItems(self)",
					'func', function (self)
						local selected_items = self.selected_items
						self.selected_items = {}
						for im, wnd_found in pairs(selected_items) do
							if wnd_found.window_state~="destroying" then
