								'MinWidth', 6,
								'MinHeight', 6,
								'MaxWidth', 6,
								'MaxHeight', 6,
								'Background', RGBA(69, 73, 81, 255),
							}),
							}),
						}),
					}),
				PlaceObj('XTemplateFunc', {
					'name', "OnMouseButtonDown(self, pos, button)",
					'func', function (self, pos, button)
						return "break"
					end,
				}),
				PlaceObj('XTemplateFunc', {
					'name', "OnMouseButtonUp(self, pos, button)",
					'func', function (self, pos, button)
						return "break"
					end,
				}),
				}),
		}),
		}),
