						'Value', 200,
						'Tag', "<stat_multiplier>",
					}),
				},
				Professions = {
					PlaceObj('SectorOperationProfession', {
						'id', "Repair",
						'display_name', T(717830910070, --[[ModItemSectorOperation RepairItems display_name]] "Механик"),
						'description', T(671435530451, --[[ModItemSectorOperation RepairItems description]] "Механик будет ремонтировать выбранные предметы."),
						'display_name_all_caps', T(886575604370, --[[ModItemSectorOperation RepairItems display_name_all_caps]] "МЕХАНИКИ"),
						'display_name_plural', T(354713063180, --[[ModItemSectorOperation RepairItems display_name_plural]] "Механик"),
						'display_name_plural_all_caps', T(162738516067, --[[ModItemSectorOperation RepairItems display_name_plural_all_caps]] "МЕХАНИКИ"),
					}),
				},
				ProgressCompleteThreshold = function (self, merc, sector, prediction)
					local item, data = SectorOperationItemToRepair(sector.Id, prediction)
					if not item then return 0 end
					local queue = SectorOperationItems_GetItemsQueue(sector.Id,"RepairItems")
					
					local max = 0
					for _, data in ipairs(queue) do
						local item = SectorOperationRepairItems_GetItemFromData(data)
						if item then
							local max_condition = item:GetMaxResource() or item:GetMaxCondition()			
							max = max + max_condition*item.RepairCost
						end
					end
					return max
				end,
				ProgressCurrent = function (self, merc, sector, prediction)
					local item, dta = SectorOperationItemToRepair(sector.Id, prediction)
					if not item then return 0 end
					local queue = SectorOperationItems_GetItemsQueue(sector.Id, "RepairItems")
					local max = 0
					for _, data in ipairs(queue) do
						local item =  SectorOperationRepairItems_GetItemFromData(data)
						if item then
							local prev_cond = item:GetCurrentResource() or item.Condition
							max = max + prev_cond*item.RepairCost + item.repair_progress
							if not prediction then
								NetUpdateHash("RepairItem_ProgressCurrent", item.id, item.class, item.WeaponResource or item.ArmorResource or item.Condition, item.repair_progress)
							end
						end
					end
					return max
				end,
				ProgressPerTick = function (self, merc, prediction)
					if not merc then return 0 end
					local sector = merc:GetSector()
					local mercs = GetOperationProfessionals(sector.Id, self.id)
					table.insert_unique(mercs, merc)
					
					local item, data = SectorOperationItemToRepair(sector.Id, prediction)
					if not item then
						return 0
					end
					-- add progress
					local sum_stat = GetSumOperationStats(mercs, "Mechanical", self:ResolveValue("stat_multiplier"))			
					return  sum_stat
				end,
				RequiredResources = {
					"Parts",
				},
				SectorMercsTick = function (self, merc)
					local sector = merc:GetSector()
					local start_time = sector.started_operations[self.id]
					local min_time = self:ResolveValue("min_time")
					local timediff =  (Game.CampaignTime - start_time)
					local min_h = (min_time*const.Scale.h)
					local ticks_left = 1 
					if timediff<min_h then
						-- does not progress first 6 (min_time) hours
						 return	
					elseif timediff==min_h then
						-- add all progress for the first 6(min_time) hours
						ticks_left = min_time*4
					end
					
					local mercs = GetOperationProfessionals(sector.Id, self.id)
					table.insert_unique(mercs, merc)

					for i=1,ticks_left do
						local item, data = SectorOperationItemToRepair(sector.Id)
						if not item then
							assert(not next(sector.sector_reapir_items_queued))
							self:Complete(sector)
							return
						end
						-- add progress
						local sum_stat = GetSumOperationStats(mercs, "Mechanical", self:ResolveValue("stat_multiplier"))


						item.Condition = floatfloor(item.Condition,0)

						local prev_cond = item:GetCurrentResource() or item.Condition
						local prev_progress = item.repair_progress
						local max_condition = item:GetMaxResource() or item:GetMaxCondition()
						local to_repair = max_condition - prev_cond


												-- обновляем ресурс, а не Condition напрямую
if item.WeaponResource then
	AddScaledProgress(item, "repair_progress", "WeaponResource", sum_stat, item.WeaponResourceMax, item.RepairCost)
	item.Condition = MulDivRound(item.WeaponResource, 100, max_condition)
	item.WeaponResourceMax = max_condition;
elseif item.ArmorResource then
	AddScaledProgress(item, "repair_progress", "ArmorResource", sum_stat, item.ArmorResourceMax, item.RepairCost)
	item.Condition = MulDivRound(item.ArmorResource, 100, max_condition)
	item.ArmorResourceMax = max_condition;
else
	AddScaledProgress(item, "repair_progress", "Condition", sum_stat, item:GetMaxCondition(), item.RepairCost)
end


local repaired =  (item:GetCurrentResource() or item.Condition) - prev_cond
repairability = item.Repairability or item.Reliability or 100
local loss = MulDivRound(repaired, (100 - repairability) * (100 - sum_stat/4), 100 * 100)
max_condition = max_condition - loss;

						
if item.ArmorResource then
	item.ArmorResource = Clamp(item.ArmorResource, 0, max_condition)
	item.ArmorResourceMax = max_condition;
  elseif item.WeaponResource then
	item.WeaponResource = Clamp(item.WeaponResource, 0, max_condition)
	item.WeaponResourceMax = max_condition;
  end


						if repaired > 0 then
							if to_repair <= self:ResolveValue("free_repair") then
							else			
								-- get one part
								local border = 0
								local cond_delta = (item:GetCurrentResource() or item.Condition) - prev_cond
						if cond_delta > 0 then
						    local restore_per_part = self:ResolveValue("restore_condition_per_Part")
						    local parts_needed = floatfloor(cond_delta / restore_per_part)
						    for i=1, parts_needed do
						        local parts, m, mbag, slot_name
						        -- попытка найти детали
						        for _, merc in ipairs(mercs) do
						            parts = merc:GetItem("Parts")
						            if parts then
						                m = merc
						                slot_name = merc:GetItemSlot(parts)
						                break
						            else
						                local bag = merc.Squad and GetSquadBagInventory(merc.Squad)
						                if bag then
						                    parts = bag:GetItem("Parts")
						                    if parts then
						                        mbag = bag
						                        slot_name = "Inventory"
						                    end
						                    break
						                end
						            end
						        end
							
						        if parts then
						            parts.Amount = parts.Amount - self:ResolveValue("parts_per_step")
						            if parts.Amount <= 0 then
						                if m then
						                    m:RemoveItem(slot_name, parts)
						                    DoneObject(parts)
						                    ObjModified(m)
						                elseif mbag then
						                    mbag:RemoveItem(slot_name, parts)
						                    DoneObject(parts)
						                    ObjModified(mbag)
						                end
						            end
						            InventoryUIRespawn()
						        else
						            -- если деталей не хватает - откат прогресса ремонта
						            --item.Condition = prev_cond
						            item.repair_progress = prev_progress
									item.Condition = prev_cond
if item.ArmorResource then
  item.ArmorResource = MulDivRound(prev_cond, max_condition, 100)
  item.ArmorResourceMax = max_condition;
elseif item.WeaponResource then
  item.WeaponResource = MulDivRound(prev_cond, max_condition, 100)
  item.WeaponResourceMax = max_condition;
end
						            CombatLog("important", T{788054483744, "Not enough parts to continue <em><activity></em> Operation in sector <SectorName(sector)>.", sector = sector, activity = self.display_name})
						            self:Complete(sector)
						            gv_Sectors[sector.Id].sector_repair_items_queued = {}
						            local queue = gv_Sectors[sector.Id].sector_repair_items_queued
						            ObjModified(queue)
						            break
						        end
						    end
						end
							end
						end
						-- unjam jammed weapon
						if item:IsWeapon() and item.jammed then
							item:RepairJammed(item.Condition, data and data.unit and gv_UnitData[data.unit])
						end
					end
				end,
				SortKey = 50,
				Tick = function (self, merc)
					return
				end,
				description = T(896760300833, --[[ModItemSectorOperation RepairItems description]] "Ремонт поврежденного снаряжения с использованием механических запчастей. Участие наемников с высокой характеристикой «<color EmStyle>Механика</color>» ускорит операцию. Оружие с состоянием ниже 90% получает износ при ремонте."),
				display_name = T(810510705491, --[[ModItemSectorOperation RepairItems display_name]] "Ремонт предметов"),
				group = "Default",
